    def validArrangement(self, pairs: List[List[int]]) -> List[List[int]]:
        graph = defaultdict(list)
        degree = defaultdict(int) # net out degree 
        for x, y in pairs: 
            graph[x].append(y)
            degree[x] += 1
            degree[y] -= 1

        start_node = None
        for k in degree: 
            if degree[k] == 1: 
                start_node = k
                break

        # If no node with out-degree > in-degree, pick any starting point (Eulerian circuit case)
        if start_node is None:
            start_node = pairs[0][0]

        ans = []

        def fn(x): 
            """Return Eulerian path via dfs."""
            while graph[x]: 
                fn(graph[x].pop()) 
            ans.append(x)

        fn(start_node)
        ans.reverse()
        return [[ans[i], ans[i+1]] for i in range(len(ans)-1)]
