from functools import lru_cache
from typing import List

def maximumTastiness(price: List[int], tastiness: List[int], maxAmount: int, maxCoupons: int) -> int:
    n = len(price)

    @lru_cache(None)
    def dp(i: int, amount_left: int, coupons_left: int) -> int:
        if i == n:
            return 0

        # Option 1: Skip current fruit
        res = dp(i + 1, amount_left, coupons_left)

        # Option 2: Buy without coupon
        p_full = price[i]
        if amount_left >= p_full:
            res = max(res, tastiness[i] + dp(i + 1, amount_left - p_full, coupons_left))

        # Option 3: Buy with coupon (if coupons available)
        if coupons_left > 0:
            p_half = price[i] // 2
            if amount_left >= p_half:
                res = max(res, tastiness[i] + dp(i + 1, amount_left - p_half, coupons_left - 1))

        return res

    return dp(0, maxAmount, maxCoupons)

